"""Legacy-compatible numeric division behavior for migrated CRMScript."""

from typing import Any


def _legacy_number(value: Any) -> float:
    """Apply legacy numeric-context coercion."""
    if value is None or value == "":
        return 0.0
    return float(value)


def safe_div(a: Any, b: Any) -> tuple[float, list[str]]:
    """Divide using Meridian CRM legacy division-by-zero semantics."""
    try:
        numerator = _legacy_number(a)
        divisor = _legacy_number(b)

        if divisor == 0.0:
            return 0.0, ["SCRIPT_DIV0"]

        return float(numerator / divisor), []
    except Exception:
        # Preserve the legacy engine's non-throwing behavior for numeric contexts.
        return 0.0, ["SCRIPT_DIV0"]
